using System.Text.Json;
using Connapse.Eval.Checks.OlmOcr;
using FluentAssertions;

namespace Connapse.Eval.Tests.Checks;

/// <summary>
/// Checks the olmOCR test ports against outcomes produced by olmocr's tests.py
/// (Fixtures/olmocr/expected.json, regenerated by generate_expected.py).
/// </summary>
[Trait("Category", "Unit")]
public class OlmOcrCheckTests
{
    private static readonly JsonElement Expected = OlmOcrMatchingTests.Expected;

    public static TheoryData<int> NormalizeCases => OlmOcrMatchingTests.Cases("normalize");
    public static TheoryData<int> CheckCases => OlmOcrMatchingTests.Cases("checks");

    [Theory]
    [MemberData(nameof(NormalizeCases))]
    public void Normalize_MatchesNormalizeText(int index)
    {
        JsonElement c = Expected.GetProperty("normalize")[index];

        OlmOcrText.Normalize(c.GetProperty("s").GetString()).Should().Be(c.GetProperty("normalized").GetString());
    }

    [Theory]
    [MemberData(nameof(CheckCases))]
    public void Run_MatchesReferenceOutcome(int index)
    {
        JsonElement c = Expected.GetProperty("checks")[index];
        OlmOcrTest test = OlmOcrTestLoader.Load(c.GetProperty("row"));

        OlmOcrOutcome outcome = test.Run(c.GetProperty("content").GetString()!);

        outcome.Passed.Should().Be(c.GetProperty("passed").GetBoolean());
        // Table explanations name the best neighbour found while iterating a Python set, so only
        // their pass/fail is compared.
        if (test is not TableTest)
            outcome.Explanation.Should().Be(c.GetProperty("explanation").GetString());
    }

    [Fact]
    public void Load_UnknownField_Throws()
    {
        using JsonDocument row = JsonDocument.Parse("""{"pdf":"a.pdf","page":1,"id":"x","type":"present","text":"hi","colour":"red"}""");

        Action act = () => OlmOcrTestLoader.Load(row.RootElement);

        act.Should().Throw<OlmOcrValidationException>().WithMessage("*colour*");
    }

    [Fact]
    public void Load_UnsupportedType_Throws()
    {
        using JsonDocument row = JsonDocument.Parse("""{"pdf":"a.pdf","page":1,"id":"x","type":"format","text":"hi","format":"bold"}""");

        Action act = () => OlmOcrTestLoader.Load(row.RootElement);

        act.Should().Throw<OlmOcrValidationException>().WithMessage("*format*");
    }

    [Fact]
    public void Load_OrderMaxDiffsOverHalf_Throws()
    {
        using JsonDocument row = JsonDocument.Parse("""{"pdf":"a.pdf","page":1,"id":"x","type":"order","before":"abcd","after":"efghij","max_diffs":3}""");

        Action act = () => OlmOcrTestLoader.Load(row.RootElement);

        act.Should().Throw<OlmOcrValidationException>().WithMessage("*too large*");
    }

    [Fact]
    public void Run_Math_IsSkipped()
    {
        using JsonDocument row = JsonDocument.Parse("""{"pdf":"a.pdf","page":1,"id":"x","type":"math","math":"x^2"}""");

        OlmOcrOutcome outcome = OlmOcrTestLoader.Load(row.RootElement).Run("x^2");

        outcome.Skipped.Should().BeTrue();
    }

    [Fact]
    public void DefaultBaselines_AddsOnePerPdfWithoutBaseline()
    {
        OlmOcrTest[] tests =
        [
            new TextPresenceTest("a.pdf", 1, "a1", "present", 0, "x"),
            new TextPresenceTest("a.pdf", 1, "a2", "absent", 0, "y"),
            new BaselineTest("b.pdf", 1, "b1", "baseline", 0),
            new TextPresenceTest("b.pdf", 1, "b2", "present", 0, "z"),
        ];

        IReadOnlyList<BaselineTest> added = OlmOcrTestLoader.DefaultBaselines(tests);

        added.Should().ContainSingle().Which.Id.Should().Be("a.pdf_baseline");
    }
}
